        array("id" => "s2011e51", "season" => 2011, "number" => 51, "name" => "Onwards to Battle! Ichigo, Mastering the Fullbring!", "airdate" => "20 Dec 2011", "runtime" => 30, "rating" => 9.3, "summary" => "Tsukishima breaks into the Xcution hideout where Ichigo is training. Learning that he was the one who attacked Uryu and Orihime, a furious Ichigo proceeds to attack Tsukishima.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/380/950693.jpg"),
